// Data types formerly generated by prost-build from build.proto.
// Now plain Rust structs with serde derives, serialized with postcard.
use bytes::Bytes;
use serde::Deserialize;
use serde::Serialize;

/// A BuildRequest describes what to run on the builder.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct BuildRequest {
    pub inputs: Vec<snix_castore::proto::Entry>,
    pub command_args: Vec<String>,
    pub working_dir: String,
    pub scratch_paths: Vec<String>,
    pub inputs_dir: String,
    pub outputs: Vec<String>,
    pub environment_vars: Vec<build_request::EnvVar>,
    pub constraints: Option<build_request::BuildConstraints>,
    pub additional_files: Vec<build_request::AdditionalFile>,
    pub refscan_needles: Vec<String>,
    pub workspace: Option<build_request::StatefulWorkspaceRequest>,
}

pub mod build_request {
    use super::*;

    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct EnvVar {
        pub key: String,

        pub value: Bytes,
    }

    #[derive(Clone, Debug, PartialEq, Default, Serialize, Deserialize)]
    pub struct BuildConstraints {
        pub system: String,
        pub min_memory: u64,
        pub available_ro_paths: Vec<String>,
        pub network_access: bool,
        pub provide_bin_sh: bool,
        #[serde(default)]
        pub provide_proc_metadata: bool,
        #[serde(default)]
        pub provide_random_devices: bool,
    }

    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct AdditionalFile {
        pub path: String,

        pub contents: Bytes,
    }

    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct StatefulWorkspaceLeaseBinding {
        pub worker_id: String,
        pub authority_class: String,
        pub job_id: String,
        pub attempt_id: String,
        pub fence_generation: u64,
    }

    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct StatefulWorkspaceRequest {
        pub mode: String,
        pub workspace_id: Option<String>,
        pub guest_path: String,
        pub snapshot_input_name: Option<String>,
        pub compatibility_digest_blake3: String,
        pub toolchain_refs: Vec<String>,
        pub quota_bytes_max: u64,
        pub quota_files_max: u32,
        pub quota_snapshots_max: u32,
        pub retention_class: String,
        pub retention_workspace_count_max: u32,
        pub retention_idle_generations_max: u64,
        pub retention_age_generations_max: u64,
        pub retention_quarantine_count_max: u32,
        pub generation: u64,
        pub lease: Option<StatefulWorkspaceLeaseBinding>,
        pub sensitive_paths: Vec<String>,
        pub secret_markers: Vec<String>,
        pub scan_depth_max: u32,
        pub path_bytes_max: u32,
        pub snapshot_enabled: bool,
        pub clean_rebuild_enabled: bool,
        pub clean_rebuild_require_declared_inputs: bool,
    }
}

/// A BuildResponse is the outcome of executing a BuildRequest.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct BuildResponse {
    pub outputs: Vec<build_response::Output>,
}

pub mod build_response {
    use super::*;

    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct Output {
        pub output: Option<snix_castore::proto::Entry>,
        pub needles: Vec<u64>,
    }
}
